package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.util.*;import java.io.*;
/** Numeric usage only: input-byte estimates and provider-reported tokens remain distinct. */
final class UsageLedger {
 static final String[] TOKENS={"promptTokenCount","candidatesTokenCount","totalTokenCount","cachedContentTokenCount","thoughtsTokenCount"};
 static JSONObject clean(JSONObject metadata)throws Exception{JSONObject out=new JSONObject();if(metadata!=null)for(String key:TOKENS)if(metadata.has(key)){Object raw=metadata.get(key);if(!(raw instanceof Number))continue;double number=((Number)raw).doubleValue();if(Double.isFinite(number)&&number>=0&&number<=1000000000&&number==Math.floor(number))out.put(key,(long)number);}return out;}
 static void record(Context c,String id,String kind,int ordinal,long bytes,JSONObject metadata)throws Exception{recordRun(c,id,kind,UUID.nameUUIDFromBytes(("legacy:"+kind+":"+id).getBytes("UTF-8")).toString(),ordinal,bytes,metadata);}
 static synchronized void recordRun(Context c,String id,String kind,String run,int ordinal,long bytes,JSONObject metadata)throws Exception{ReviewStore.validId(run);if(!kind.matches("image|video|meeting")||ordinal<1||ordinal>10000||bytes<0||bytes>1000000000)throw new IOException("利用量の記録形式が不正です");CancellableWork.key(kind,id);String key=kind+":"+id+":"+run+":"+ordinal;JSONObject doc=ReviewStore.read(c,"usage-ledger");JSONArray old=doc.optJSONArray("items"),next=new JSONArray();JSONObject row=null;long now=System.currentTimeMillis();for(int i=0;old!=null&&i<old.length();i++){JSONObject entry=old.getJSONObject(i);if(key.equals(entry.optString("key")))row=entry;else if(entry.optLong("at")>=now-90L*86400000)next.put(entry);}if(row==null)row=new JSONObject().put("key",key).put("kind",kind).put("at",now).put("inputBytesEstimate",bytes);JSONObject usage=clean(metadata);if(usage.length()>0)row.put("providerTokens",usage);next.put(row);JSONArray bounded=new JSONArray();for(int i=Math.max(0,next.length()-500);i<next.length();i++)bounded.put(next.get(i));ReviewStore.write(c,"usage-ledger",new JSONObject().put("items",bounded));}
 static void response(JSONObject response){try{CancellableWork.Task task=CancellableWork.current.get();if(task!=null)recordRun(task.context,task.record.getString("id"),task.record.getString("kind"),task.record.getString("usageRun"),task.record.optInt("sentRequests"),task.record.optLong("lastInputBytes"),response.optJSONObject("usageMetadata"));}catch(Exception ignored){}}
 static JSONObject read(Context c)throws Exception{JSONObject doc=ReviewStore.read(c,"usage-ledger"),rates=ReviewStore.read(c,"usage-rates");JSONArray rows=doc.optJSONArray("items"),groups=new JSONArray();TreeMap<String,JSONObject> map=new TreeMap<>();for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.optLong("at")<System.currentTimeMillis()-90L*86400000)continue;String day=java.time.Instant.ofEpochMilli(row.getLong("at")).atZone(java.time.ZoneId.systemDefault()).toLocalDate().toString(),key=day+":"+row.getString("kind");JSONObject group=map.get(key);if(group==null){group=new JSONObject().put("day",day).put("kind",row.getString("kind")).put("requests",0).put("reportedRequests",0).put("inputReportedRequests",0).put("outputReportedRequests",0).put("inputBytesEstimate",0).put("inputTokens",0).put("outputTokens",0);map.put(key,group);}group.put("requests",group.getInt("requests")+1).put("inputBytesEstimate",group.getLong("inputBytesEstimate")+row.optLong("inputBytesEstimate"));JSONObject tokens=row.optJSONObject("providerTokens");if(tokens!=null){if(tokens.has("promptTokenCount"))group.put("inputReportedRequests",group.optInt("inputReportedRequests")+1);if(tokens.has("candidatesTokenCount"))group.put("outputReportedRequests",group.optInt("outputReportedRequests")+1);group.put("reportedRequests",group.getInt("reportedRequests")+1).put("inputTokens",group.getLong("inputTokens")+tokens.optLong("promptTokenCount")).put("outputTokens",group.getLong("outputTokens")+tokens.optLong("candidatesTokenCount"));}}for(JSONObject group:map.values()){if(rates.has("inputPerMillion"))group.put("tokenCostEstimate",(group.getLong("inputTokens")*rates.getDouble("inputPerMillion")+group.getLong("outputTokens")*rates.getDouble("outputPerMillion"))/1000000d);groups.put(group);}return new JSONObject().put("items",groups).put("rates",rates).put("scope","追加後のスマホ画像生成・会議解析・動画生成の送信試行を最大500件・90日分記録。API応答に数値のusageMetadataがある場合だけ実報告トークンを記録。入力バイトはローカル見積り。グラス会話・他アプリ・過去分・請求総額は対象外。動画秒数・画像料金・キャッシュ・思考等を含む確定料金ではありません");}
 static void rates(Context c,JSONObject v)throws Exception{double input=v.getDouble("inputPerMillion"),output=v.getDouble("outputPerMillion");String currency=v.getString("currency");if(!Double.isFinite(input)||!Double.isFinite(output)||input<0||output<0||input>10000000||output>10000000||!currency.matches("JPY|USD"))throw new IOException("単価と通貨を確認してください");ReviewStore.write(c,"usage-rates",new JSONObject().put("inputPerMillion",input).put("outputPerMillion",output).put("currency",currency).put("at",System.currentTimeMillis()));}
 private UsageLedger(){}
}
